  const state = this.featureQualityMonitor.getState();
  if (state === FeatureQualityState.DROUGHT) effectiveVisualConfidence = 0;
  else if (state === FeatureQualityState.POOR) effectiveVisualConfidence *= 0.3;
}
const fusedOrientation = this.complementaryFilter.fuse(
  imuOrientation, null, effectiveVisualConfidence
);
```

This avoids modifying `ComplementaryFilter` itself and is the least invasive change.

#### 2g. Dispose (around line 1667)

Add cleanup for both new components:

```typescript
if (this.featureQualityMonitor) {
  this.featureQualityMonitor.dispose();
  this.featureQualityMonitor = null;
}
if (this.planeModelPersistence) {
  this.planeModelPersistence.dispose();
  this.planeModelPersistence = null;
}
```

#### 2h. Memory reset (in `performMemoryReset`, around line 1210)

Add resets for both new components:

```typescript
if (this.featureQualityMonitor) {
  this.featureQualityMonitor.reset();
}
if (this.planeModelPersistence) {
  this.planeModelPersistence.reset();
}
```

