    // 姿勢データを受信したらトラッキングを有効化
    if (!this.imuTrackingEnabled) {
      this.imuTrackingEnabled = true;
      // 平面の回転をIMU座標系に変換（一度だけ）
      this.adjustPlaneRotationForIMU();
      console.log("IMU tracking enabled (orientation data received)");
    }
